    assert.equal(geometry.workspaceInNativeSidebar, false); assert.ok(geometry.workspace.x >= geometry.chat.right); assert.ok(geometry.workspace.width > 400); assert.ok(geometry.workspace.right <= width + 1); assert.ok(geometry.documentWidth <= width + 1); dimensions.push(geometry);
