  assert.equal(preserved.editor, true); assert.equal(preserved.frame, true); assert.equal(preserved.controller, true); assert.equal(preserved.dirty, true); assert.ok(preserved.draft.endsWith(' · 整应用外壳真实输入')); assert.equal(await form.inputValue(), '整应用网页未提交内容'); assert.equal(metrics.spawn, 1); assert.equal(metrics.close, 0);
  await page.evaluate(() => { window.appProbe.input = document.querySelector('[data-lexical-editor=true]'); });
  const submittedText = await page.evaluate(() => window.testNative.controller().content('DOC-01').document.getSnapshot().text);
  await work.getByRole('button', { name: '保存文件', exact: true }).click();
  await page.waitForFunction(() => !window.testNative.controller().content('DOC-01').document.getSnapshot().dirty);
