  await editor.press('Control+End'); await page.keyboard.insertText(' UNSAVED_AFTER_SAVE');
  await page.getByRole('button', { name: '编辑布局', exact: true }).click();
  assert.equal(await page.evaluate(() => window.appProbe.input === document.querySelector('[data-lexical-editor=true]')), true);
  await page.screenshot({ path: 'test-output/application-shell-editor.png', fullPage: true });
  await page.getByRole('button', { name: '取消', exact: true }).click();
  await page.getByRole('combobox', { name: '布局预设', exact: true }).selectOption('review');
  await page.screenshot({ path: 'test-output/application-shell-review.png', fullPage: true });
  assert.equal(await form.inputValue(), '整应用网页未提交内容');
  await page.getByRole('combobox', { name: '布局预设', exact: true }).selectOption('development');
