  await page.waitForFunction(() => document.querySelector('.xterm-screen')?.textContent.includes('AFTER:DSHOME_KEEP_123'));
  assert.equal(await page.evaluate(() => window.appProbe.terminal === window.testNative.controller().content('TERM-01').view), true);
  await page.screenshot({ path: 'test-output/application-shell-daily.png', fullPage: true });
