  assert.deepEqual(await page.evaluate(() => window.testNative.errors), []);
  await page.evaluate(() => window.testNative.ctx.theme.setTheme('dark'));
  await page.waitForFunction(() => document.documentElement.getAttribute('data-ds-theme-source') === 'dark' && document.body.hasAttribute('data-ds-dark-theme'));
  const dark = await page.locator('.dshome-app-conversation').evaluate(e => ({ background: getComputedStyle(e).backgroundColor, color: getComputedStyle(e).color })); assert.notEqual(dark.background, 'rgb(255, 255, 255)');
  await page.evaluate(() => window.testNative.ctx.theme.setTheme('light'));
