  const declined = await page.evaluate(() => window.__dshomePluginWorkbench.closeWorkspace().then(() => false, () => true)); assert.equal(declined, true); assert.equal(await page.evaluate(() => window.appProbe.editor.isConnected && window.testNative.controller().content('DOC-01').document.getSnapshot().dirty), true);
  page.once('dialog', d => d.accept()); await page.evaluate(() => window.__dshomePluginWorkbench.closeWorkspace());
